		if (branch == "" && !cfg.Issues) || (branch != "" && !cfg.PRs) {
			continue
		}

		if org != cfg.Org ||
			(cfg.Repo != "" && cfg.Repo != repo) ||
			(cfg.Branch != "" && branch != "" && cfg.Branch != branch) {
			continue
		}

		if label != "" && !cfg.Re.MatchString(label) {
			continue
		}
		filtered = append(filtered, cfg)
	}
	return filtered
}

