func (g *Group) loadPaths(r io.Reader) error {
	s := bufio.NewScanner(r)

	for s.Scan() {
		l := strings.TrimSpace(s.Text())
		if l == "" || l[0] == '#' {
			// Ignore comments and empty lines.
			continue
		}

		g.Paths[l] = true
	}

	if err := s.Err(); err != nil {
		return fmt.Errorf("scan error: %v", err)
	}

	return nil
}

