func ReleaseApplicationLock(appName string) {
	var err error
	retries := 3
	for i := 0; i < retries; i++ {
		err = releaseApplicationLockOnce(appName)
		if err == nil {
			return
		}
		time.Sleep(time.Second * time.Duration(i+1))
	}
	log.Error(err)
}

