		return nil, nil, pathMatched
	}

	if len(matches) == 1 {

		return matches[0].Route.(*Route), matches[0].Params, pathMatched
	}


	result := rt.ofFirstDefinedRoute(matches)
	return result.Route.(*Route), result.Params, pathMatched
}

