	fiTmp, err := os.Lstat(tmplock.Name())
	if err != nil {
		return err
	}
	fiLock, err := os.Lstat(name)
	if err != nil {

		if os.IsNotExist(err) {
			return ErrNotExist
		}
		return err
	}


	if os.SameFile(fiTmp, fiLock) {
		return nil
	}

	proc, err := l.GetOwner()
	switch err {
	default:

		return err
	case nil:
		if proc.Pid != os.Getpid() {
			return ErrBusy
		}
	case ErrDeadOwner, ErrInvalidPid:

	}


	err = os.Remove(name)
	if err != nil {

		if !os.IsNotExist(err) {
			return err
		}
	}


	return l.TryLock()
}

