func ParseInt(b []byte) (int64, error) {
	var val int64

	if len(b) == 0 {
		return 0, errorInvalidUint64(b)
	}

	if b[0] == '-' {
		const max = Int64Min
		const lim = max / 10

		if b = b[1:]; len(b) == 0 {
			return 0, errorInvalidUint64(b)
		}

		for _, d := range b {
			if !(d >= '0' && d <= '9') {
				return 0, errorInvalidInt64(b)
			}

			if val < lim {
				return 0, errorOverflowInt64(b)
			}

			val *= 10
			x := int64(d - '0')

			if val < (max + x) {
				return 0, errorOverflowInt64(b)
			}

			val -= x
		}
	} else {
		const max = Int64Max
		const lim = max / 10

		for _, d := range b {
			if !(d >= '0' && d <= '9') {
				return 0, errorInvalidInt64(b)
			}
			x := int64(d - '0')

			if val > lim {
				return 0, errorOverflowInt64(b)
			}

			if val *= 10; val > (max - x) {
				return 0, errorOverflowInt64(b)
			}

			val += x
		}
	}

	return val, nil
}

