			}


			prefix = path[:i]
			if !bytes.Equal(prefix, kPrefix) {
				return k, v
			}

			if last {

				if k, v = c.Seek(prefix); bytes.Equal(k, prefix) {
					return k, v
				}
				return nil, nil
			}

		default:

			next := path[len(prefix)]
			if next == ':' || next == '*' {
				return k, v
			}

			prefix = path[:i]
			k, v = c.Seek(prefix)

			if last {

				if bytes.Equal(k, prefix) {
					return k, v
				}
				return nil, nil
			}

			if !bytes.HasPrefix(k, prefix) {
				return nil, nil
			}
		}
	}
}

