func (e PanicError) Format(s fmt.State, verb rune) {
	switch verb {
	case 's':
		io.WriteString(s, e.Error())
	case 'v':
		io.WriteString(s, e.Error())
		for _, f := range e.stack {
			io.WriteString(s, "\n")
			if s.Flag('+') {
				fmt.Fprintf(s, "%s\n\t", f.Function)
			}
			fmt.Fprintf(s, "%s:%d", f.File, f.Line)
		}
	}
}

