func (v *VM) totalNetworkAdapters(vmx map[string]string) int {
	var total int
	prefix := "ethernet"

	for key := range vmx {
		if strings.HasPrefix(key, prefix) {
			ethN := strings.Split(key, ".")[0]
			number, _ := strconv.Atoi(strings.Split(ethN, prefix)[1])

			if number > total {
				total = number
			}
		}
	}

	return total
}

