func (s *Server) ServeTCP(ln net.Listener) (err error) {
	if l, ok := ln.(*net.TCPListener); ok {
		ln = tcpKeepAliveListener{TCPListener: l}
	}
	if s.TLSConfig != nil {
		ln = tls.NewListener(ln, s.TLSConfig)
	}

	err = s.Server.Serve(ln)
	if err == http.ErrServerClosed {
		return nil
	}
	return
}

