	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		mw := &minifyResponseWriter{mw: minifier.ResponseWriter(w, r), w: w}
		h.ServeHTTP(mw, r)
		if err := mw.Close(); err != nil && err != minify.ErrNotExist && logFunc != nil {
