	verbSet := map[Verb]struct{}{verb: struct{}{}}
	for _, v := range verbs {
		verbSet[v] = struct{}{}
	}

	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if _, ok := verbSet[Verb(r.Method)]; ok {
			h.ServeHTTP(w, r)
		} else {
			w.WriteHeader(http.StatusBadRequest)
		}
	})
}

