func (t Tuple) WriteTo(w io.Writer) (n int, err error) {
	// write header
	wrote, err := t.Header.WriteTo(w)
	if err != nil {
		return int(wrote), nil
	}

	n, err = w.Write(t.data)
	if err != nil {
		return int(n), err
	}
	return int(wrote) + n, nil
}

