		if rd.Data["RequestStartTime"] != nil {
			rd.Data["RequestTimes"] = time.Since(rd.Data["RequestStartTime"].(time.Time)).Nanoseconds() / 1e6
			rd.Data["RequestStartTime"] = nil                                            
